arguments.command:
./novamind-operation python-c "
import novamind_api as nm
import inspect

# Check signatures
for func_name in ['set_targeted_ad_spend', 'set_ads_strength', 'set_lead_promotion', 'set_daily_spend', 'set_capacity_tier', 'set_prices', 'set_model_tiers', 'set_usage_quotas', 'start_research_project', 'send_enterprise_deal']:
    func = getattr(nm, func_name.split('.')[0] if '.' in func_name else nm, None)
    if func_name.startswith('s'):
        for mod in ['pricing', 'marketing', 'infrastructure', 'enterprise', 'research']:
            m = getattr(nm, mod)
            if hasattr(m, func_name):
                func = getattr(m, func_name)
                print(f'--- {func_name} ---')
                print(inspect.signature(func))
                print()
                break
"

