import novamind_api as nm
import json

for g in ['S1','S2','S3']:
    ins = nm.market.get_group_insights(group_id=g)
    print(f'=== {g} ===')
    for k in sorted(ins.keys()):
        v = ins[k]
        if k.endswith('_matrix'):
            print(f'  {k}:')
            if isinstance(v, dict):
                for kk, vv in v.items():
                    print(f'    {kk}: {vv}')
            else:
                print(f'    {v}')
        elif k.endswith('_vector'):
            print(f'  {k}: {v}')
"

