import novamind_api as nm

# Count subscriptions created this week (days 120-126) by status
for day in range(120, 127):
    for status in ['lead', 'subscribed', 'cancelled', 'lost']:
        result = nm.query(f\"SELECT COUNT(*) as n FROM subscriptions WHERE start_day={day} AND status='{status}'\")
        n = result['rows'][0]['n']
        if n > 0:
            print(f'Day {day} {status}: {n}')
"

